      "issue_id": "SPA-N-005",
      "position": "PUSHBACK",
      "evidence": "Preserve appropriate remedies for fraud and deliberate concealment, and rights that cannot lawfully be excluded."
    },
    {
      "issue_id": "SPA-N-006",
      "position": "PUSHBACK",
      "evidence": "Reject blanket disclosure of public records and documents merely referred to."
    },
    {
      "issue_id": "SPA-N-007",
      "position": "PUSHBACK",
      "evidence": "Prefer no knowledge exclusion; any compromise should be limited to actual knowledge of specified Buyer individuals"
    },
    {
      "issue_id": "SPA-N-008",
      "position": "PUSHBACK",
      "evidence": "Require satisfaction of clause 11.3 conditions—not merely delivery of a consent letter."
    },
    {
      "issue_id": "SPA-N-009",
      "position": "PUSHBACK",
      "evidence": "direct payment from Completion proceeds; and binding release arrangements effective at Completion."
    },
    {
      "issue_id": "SPA-N-010",
      "position": "PUSHBACK",
      "evidence": "Allocate agreed transaction-related liabilities to the Seller through payment, a debt-like deduction or another express adjustment, supported by an indemnity."
    },
    {
      "issue_id": "SPA-N-011",
      "position": "PUSHBACK",
      "evidence": "Expand the indemnity beyond the invoice to relevant ownership, infringement, dispute and remediation losses."
    },
    {
      "issue_id": "SPA-N-012",
      "position": "PUSHBACK",
      "evidence": "Require a prompt, documented investigation, preservation of evidence, containment and an assessment of applicable privacy, contractual and notification duties."
    },
    {
      "issue_id": "SPA-N-013",
      "position": "PARTIAL",
      "evidence": "Use consent rights and price protection where justified. Do not automatically classify the full AUD 330,000 as debt"
    },
    {
      "issue_id": "SPA-N-014",
      "position": "PUSHBACK",
      "evidence": "Confine the general warranty regime expressly to general warranty claims."
    },
    {
      "issue_id": "SPA-N-015",
      "position": "PUSHBACK",
      "evidence": "DD-012’s share register is evidence, not a complete title review."
    },
    {
      "issue_id": "SPA-N-016",
      "position": "PUSHBACK",
      "evidence": "Seek appropriate standalone limits and survival for IP warranties, alongside specific protection for Ironquay."
    }
  ],
